//! Frozen legacy outputs are input data, never regenerated by this implementation.
use differens_narrate::{OutputFormat, format_changes, narrate};
use differens_tiers::{Presence, diff_with_tier};
use serde_json::{Value, json};

fn projected(value: Value) -> Value {
    match value {
        Value::Array(values) => Value::Array(values.into_iter().map(projected).collect()),
        Value::Object(values) => Value::Object(
            values
                .into_iter()
                .filter(|(key, _)| {
                    !matches!(
                        key.as_str(),
                        "contentHash" | "structureHash" | "height" | "scalarType"
                    )
                })
                .map(|(key, v)| (key, projected(v)))
                .collect(),
        ),
        value => value,
    }
}
#[test]
fn legacy_pipeline_and_presentation_contracts() {
    let cases: Value =
        serde_json::from_str(include_str!("../../../fixtures/parity/pipeline.json")).unwrap();
    let correction: Value = serde_json::from_str(include_str!(
        "../../../fixtures/corrections/markup-metadata.json"
    ))
    .unwrap();
    for case in cases.as_array().unwrap() {
        let id = case["id"].as_str().unwrap();
        let path = case["path"].as_str().unwrap();
        let result = diff_with_tier(
            case["old"].as_str().unwrap().as_bytes(),
            case["new"].as_str().unwrap().as_bytes(),
            path,
            path,
            Presence {
                old_exists: !id.ends_with("-added"),
                new_exists: !id.ends_with("-removed"),
            },
        );
        let mut actual = projected(
            json!({"changes":result.changes,"nodeCount":result.node_count,"tier":result.tier as u8}),
        );
        if let Some(ref fallback) = result.fallback {
            actual["fallback"] = json!(fallback);
        }
        let expected = if id == correction["id"] {
            &correction["expected"]
        } else {
            &case["expected"]
        };
        assert_eq!(&actual, expected, "pipeline {id}");
        let narrated = narrate(&result.changes, Some(path));
        let mut expected_narrative = case["narrated"].clone();
        if id == correction["id"] {
            expected_narrative[0]["action"] = correction["expected"]["changes"][0].clone();
        }
        assert_eq!(
            projected(serde_json::to_value(&narrated).unwrap()),
            expected_narrative,
            "narration {id}"
        );
        for (name, format) in [
            ("terminal", OutputFormat::Terminal),
            ("markdown", OutputFormat::Markdown),
            ("llm", OutputFormat::Llm),
        ] {
            assert_eq!(
                json!(format_changes(&narrated, format).unwrap()),
                case["formats"][name],
                "format {name}, fixture {id}"
            );
        }
    }
}
